-- Product page content → products.metadata.pdp
-- Environment: staging
--
-- Generated by scripts/generate-product-pdp-sql.mjs. Do not hand-edit: regenerate.
-- Source: brellohealth-purchase-journey/start-wellness.json
--         + products.config.ts (the website-slug → platform-uuid map, per env)
--
-- WHAT THIS WRITES
--   The editorial content of the product detail page — the "What is …?" body, the
--   studied benefits and the academic citations behind them, the gallery, the
--   path-to-care steps. None of it is derivable from the product row, and none of
--   it is reachable from WooCommerce (its API returns description: "" — the copy
--   lives in Elementor widgets).
--
-- WHAT IT DOES NOT WRITE
--   Price. Nexus is already the pricing source of truth: the marketing site pulls
--   price and cadence *from* the platform, precisely because hand-typed prices had
--   drifted — MICC once advertised "was $199" against a real $199 charge, showing
--   the actual price as a saving. Nothing here touches price_cents.
--
-- SAFE TO RE-RUN
--   Idempotent. `||` is a shallow jsonb merge, so it replaces the 'pdp' key and
--   leaves every other key in metadata intact — that blob is shared, and a bare
--   SET metadata = '{…}' would silently drop other producers' keys.
--
-- SAFE AGAINST THE WRONG ROW
--   Matched on the product uuid AND the Brello tenant. Every environment's products
--   table also holds other tenants' rows (production carries CareLink-owned
--   compounded-* products), so the tenant predicate means a stale uuid updates
--   nothing rather than something else's row. The tenant is resolved by slug because
--   its uuid differs per environment.
--
-- 8 products in staging.

BEGIN;

-- compounded-tirzepatide — Compounded Tirzepatide
UPDATE public.products p
   SET metadata   = COALESCE(p.metadata, '{}'::jsonb) || jsonb_build_object('pdp', '{"badge":"Best Seller","shortDesc":"Our most comprehensive GLP-1 plan to help you stick to your goals.","description":"Learn more about our Compounded Tirzepatide program — clinician-prescribed, transparently priced, and shipped from a USA-based 503A partner pharmacy.","images":["https://www.brellohealth.com/wp-content/uploads/2025/01/tirzepatide-thumbnail.jpg","https://www.brellohealth.com/wp-content/uploads/2026/03/image-brello.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-5.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-10.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-9.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-8.png"],"about":{"heading":"What is Tirzepatide?","image":"https://www.brellohealth.com/wp-content/uploads/2026/03/Vials-Frame-1.jpg","paragraphs":[{"text":"GLP-1 is a naturally occurring hormone that supports the body''s mechanisms for metabolic balance after meals.","citation":1},{"text":"As routines get busy and stress builds, many people find it harder to stay consistent with nutrition, movement, and daily habits.","citation":2}],"note":"The compounded GLP-1 medication included in this plan is tirzepatide.","benefitsHeading":"Studies examine GLP-1''s potential role in:","benefits":[{"lead":"Feeling lighter","rest":"and more comfortable in daily movements","citation":3},{"lead":"Improved consistency","rest":"with nutrition habits","citation":4},{"lead":"Greater confidence","rest":"staying on track week to week","citation":5}],"citations":["Kahal H, Kilpatrick ES, Wilding JPH. Tirzepatide: a dual GIP/GLP-1 receptor agonist for the treatment of type 2 diabetes. Diabetologia. 2023;66(1):1-14","Schwabe L, Wolf OT. Stress prompts habit behavior in humans. J Neurosci. 2009;29(22):7191-7198","Garvey WT, Batterham RL, Bhatta M, et al. Association between weight reduction achieved with tirzepatide and health-related quality of life in people with overweight or obesity. Obesity (Silver Spring). 2025;33(4):769-780","Hartman ML, Sanyal AJ, Aleppo G, et al. Effects of tirzepatide on body weight and cardiometabolic risk factors in people with overweight or obesity: a post hoc analysis of the SURPASS clinical trial program. Diabetes Obes Metab. 2023;25(2):485-496","Rubino D, Abrahamsson N, Davies M, et al. Continued treatment with tirzepatide for maintenance of weight reduction in adults with obesity: a randomized clinical trial. JAMA. 2024;331(1):31-43"]},"steps":[{"n":"1","title":"Submit Your Application","body":"Complete an online intake form."},{"n":"2","title":"Provider Review","body":"A healthcare provider will review your information to determine if you qualify for prescription medication."},{"n":"3","title":"Direct-To-Door Delivery","body":"If approved, your medication will be shipped to your doorstep by our partner pharmacy."},{"n":"4","title":"Ongoing Support","body":"We care about your journey. You can always reach out if you need guidance or support."}]}'::jsonb),
       updated_at = now()
  FROM public.tenants t
 WHERE p.tenant_id = t.id
   AND t.slug      = 'brello'
   AND p.id        = '25c28469-5755-4ec0-973c-c27ba423c4e2'::uuid;

