-- compounded-nad — Compounded NAD+
UPDATE public.products p
   SET metadata   = COALESCE(p.metadata, '{}'::jsonb) || jsonb_build_object('pdp', '{"badge":"New Arrival","shortDesc":"For women trying to juggle everything while running on fumes.","description":"Learn more about our Compounded NAD+ program — clinician-prescribed, transparently priced, and shipped from a USA-based 503A partner pharmacy.","images":["https://www.brellohealth.com/wp-content/uploads/2026/02/nad-thumb-79.webp","https://www.brellohealth.com/wp-content/uploads/2026/03/image-brello.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-5.png","https://www.brellohealth.com/wp-content/uploads/2026/02/1-2.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-4.png","https://www.brellohealth.com/wp-content/uploads/2026/02/3.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-6.png"],"about":{"heading":"What is NAD+?","image":"https://www.brellohealth.com/wp-content/uploads/2026/03/thumb-nad.png","paragraphs":[{"text":"NAD+ (Nicotinamide Adenine Dinucleotide) is a natural coenzyme found in every cell of your body. It plays an important role in metabolic processes, helping cells turn nutrients into usable energy while supporting many everyday cellular functions.","citation":1},{"text":"As we age, NAD+ levels naturally decline. This typical biological change can influence how efficiently our cells function over time.","citation":2}],"benefitsHeading":"Studies examine NAD+''s potential role in:","benefitsIntro":"When NAD+ support is appropriately prescribed and dosed under provider guidance, some women report:","benefitsImage":"https://www.brellohealth.com/wp-content/uploads/2026/03/Scrolling-Pics.jpg","benefits":[{"lead":"Assisting in reducing the daily impact of stress","citation":3},{"lead":"Supporting mechanisms involved in promoting physical activity","citation":4},{"lead":"Neuroprotection","rest":"to stay on point","citation":5}],"citations":["Houtkooper RH, Cantó C, Auwerx J. NAD+ homeostasis as a hub for metabolic control in health and disease. Cell Metab. 2010;11(5):430-441. doi:10.1016/j.cmet.2010.04.001; Verdin E, Ott M. NAD+ in aging, metabolism, and disease. Trends Cell Biol. 2015;25(9):431-441. doi:10.1016/j.tcb.2015.04.002","Gomes AP, Price NL, Ling AZ, et al. Declining NAD+ induces a pseudohypoxic state disrupting cellular energy homeostasis and mitochondrial function in human cells. Cell Metab. 2013;17(3):392-405. doi:10.1016/j.cmet.2013.02.003","Fang EF, Lautrup S, Ho YS, et al. NAD+ in aging: molecular mechanisms and translational implications. Trends Mol Med. 2017;23(10):899-916. doi:10.1016/j.molmed.2017.08.001","de Picciotto NE, Gano LB, Johnson LC, et al. Nicotinamide mononucleotide supplementation reverses vascular dysfunction and oxidative stress with aging in mice. Aging Cell. 2016;15(5):973-977. doi:10.1111/acel.12488","Lautrup S, Sinclair DA, Mattson MP, Fang EF. NAD+ in brain aging and neurodegenerative disorders. Cell Metab. 2019;30(4):630-655. doi:10.1016/j.cmet.2019.09.015"]},"steps":[{"n":"1","title":"Submit Your Application","body":"Complete an online intake form."},{"n":"2","title":"Provider Review","body":"A healthcare provider will review your information to determine if you qualify for prescription medication."},{"n":"3","title":"Direct-To-Door Delivery","body":"If approved, your medication will be shipped to your doorstep by our partner pharmacy."},{"n":"4","title":"Ongoing Support","body":"We care about your journey. You can always reach out if you need guidance or support."}]}'::jsonb),
       updated_at = now()
  FROM public.tenants t
 WHERE p.tenant_id = t.id
   AND t.slug      = 'brello'
   AND p.id        = 'c89feb57-ba73-4123-b719-12a9e93254dc'::uuid;

