UPDATE public.products p
   SET metadata   = COALESCE(p.metadata, '{}'::jsonb) || jsonb_build_object('pdp', '{"subBadge":"Empowered & Confident","shortDesc":"Support for overall well-being, clarity, and vitality.","description":"Learn more about our GLP-1 & NAD+ program — clinician-prescribed, transparently priced, and shipped from a USA-based 503A partner pharmacy.","images":["https://www.brellohealth.com/wp-content/uploads/2025/01/tirzepatide-thumbnail.jpg","https://www.brellohealth.com/wp-content/uploads/2026/03/image-brello.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-5.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-10.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-9.png","https://www.brellohealth.com/wp-content/uploads/2026/02/NEW_EXCLUSIVE-MEMBER-ACCESS-Images_1.1-8.png"],"about":{"sections":[{"heading":"How GLP-1 Works","image":"https://www.brellohealth.com/wp-content/uploads/2026/02/empowered-thumb-1.png","paragraphs":[{"text":"GLP-1 is a naturally occurring hormone that supports the body''s mechanisms for metabolic balance after meals.","citation":1}],"benefitsHeading":"Studies examine GLP-1''s potential role in:","benefits":[{"lead":"Feeling lighter","rest":"and more comfortable in daily movements","citation":2},{"lead":"Improved consistency","rest":"with nutrition habits","citation":3},{"lead":"Greater confidence","rest":"staying on track week to week","citation":4}]},{"heading":"How NAD+ Works","image":"https://www.brellohealth.com/wp-content/uploads/2026/02/girl-nad.jpg","paragraphs":[{"text":"NAD+ is a natural coenzyme found in every cell of your body. It plays an important role in how cells turn nutrients into usable energy.","citation":5},{"text":"As we age, NAD+ levels naturally decline.","citation":6}],"benefitsHeading":"Studies examine NAD+''s potential role in:","benefits":[{"lead":"Assisting in reducing the daily impact of stress","citation":7},{"lead":"Supporting mechanisms involved in promoting physical activity","citation":8},{"lead":"Neuroprotection","rest":"to stay on point","citation":9}]}],"citations":["Kahal H, Kilpatrick ES, Wilding JPH. Tirzepatide: a dual GIP/GLP-1 receptor agonist for the treatment of type 2 diabetes. Diabetologia. 2023;66(1):1-14","Garvey WT, Batterham RL, Bhatta M, et al. Association between weight reduction achieved with tirzepatide and health-related quality of life in people with overweight or obesity. Obesity (Silver Spring). 2025;33(4):769-780","Hartman ML, Sanyal AJ, Aleppo G, et al. Effects of tirzepatide on body weight and cardiometabolic risk factors in people with overweight or obesity: a post hoc analysis of the SURPASS clinical trial program. Diabetes Obes Metab. 2023;25(2):485-496","Rubino D, Abrahamsson N, Davies M, et al. Continued treatment with tirzepatide for maintenance of weight reduction in adults with obesity: a randomized clinical trial. JAMA. 2024;331(1):31-43","Houtkooper RH, Cantó C, Auwerx J. NAD+ homeostasis as a hub for metabolic control in health and disease. Cell Metab. 2010;11(5):430-441. doi:10.1016/j.cmet.2010.04.001; Verdin E, Ott M. NAD+ in aging, metabolism, and disease. Trends Cell Biol. 2015;25(9):431-441. doi:10.1016/j.tcb.2015.04.002","Gomes AP, Price NL, Ling AZ, et al. Declining NAD+ induces a pseudohypoxic state disrupting cellular energy homeostasis and mitochondrial function in human cells. Cell Metab. 2013;17(3):392-405. doi:10.1016/j.cmet.2013.02.003","Fang EF, Lautrup S, Ho YS, et al. NAD+ in aging: molecular mechanisms and translational implications. Trends Mol Med. 2017;23(10):899-916. doi:10.1016/j.molmed.2017.08.001","de Picciotto NE, Gano LB, Johnson LC, et al. Nicotinamide mononucleotide supplementation reverses vascular dysfunction and oxidative stress with aging in mice. Aging Cell. 2016;15(5):973-977. doi:10.1111/acel.12488","Lautrup S, Sinclair DA, Mattson MP, Fang EF. NAD+ in brain aging and neurodegenerative disorders. Cell Metab. 2019;30(4):630-655. doi:10.1016/j.cmet.2019.09.015"]},"includes":["GLP-1 (if approved)","NAD+ (if approved)","Provider review & ongoing support","Fitness & nutrition classes included","Private community"],"steps":[{"n":"1","title":"Submit Your Application","body":"Complete an online intake form."},{"n":"2","title":"Provider Review","body":"A healthcare provider will review your information to determine if you qualify for prescription medication."},{"n":"3","title":"Direct-To-Door Delivery","body":"If approved, your medication will be shipped to your doorstep by our partner pharmacy."},{"n":"4","title":"Ongoing Support","body":"We care about your journey. You can always reach out if you need guidance or support."}]}'::jsonb),
       updated_at = now()
  FROM public.tenants t
 WHERE p.tenant_id = t.id
   AND t.slug      = 'brello'
   AND p.id        = 'dba95f79-fa2b-4e19-94a5-d5b9cfe47c1d'::uuid;

